import polars as pl

df = pl.DataFrame({"a": pl.Series([1, 2], dtype=pl.Int32), "b": ["x", "y"]})
target = {"a": pl.Int64, "b": pl.String}
try:
    df.match_to_schema(target)
except Exception as e:
    print(type(e).__name__)

out = df.match_to_schema(target, integer_cast="upcast")
print(out.schema)
